#!/usr/bin/env node
/*
 * Maintainer helper: snapshot the host application's theme tokens for
 * pixel-accurate previews and the design gate.
 *
 * The host theme is product styling and is NOT redistributed with this
 * repository. Running this script is optional; when the generated file is
 * absent the gallery falls back to `test/fixtures/theme-fallback.css`.
 *
 * Usage:
 *   node scripts/extract-theme.mjs [--asar <path-to-app.asar>] [--out <file>]
 *
 * Defaults:
 *   macOS: /Applications/DeepSeek Harness.app/Contents/Resources/app.asar
 *   out:   test/fixtures/dsh-theme.css   (git-ignored)
 *
 * Env: DSH_ASAR can provide the asar path.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const repo = joinedRepoRoot()
const argv = process.argv.slice(2)
const arg = (name, fallback) => {
  const i = argv.indexOf('--' + name)
  return i >= 0 && argv[i + 1] ? argv[i + 1] : fallback
}

function joinedRepoRoot() {
  return resolve(here, '..')
}

const candidates = [
  process.env.DSH_ASAR,
  '/Applications/DeepSeek Harness.app/Contents/Resources/app.asar'
].filter(Boolean)
const asarPath = arg(
  'asar',
  candidates.find((p) => existsSync(p))
)
const outPath = resolve(repo, arg('out', 'test/fixtures/dsh-theme.css'))

if (!asarPath || !existsSync(asarPath)) {
  console.error('未找到宿主应用 app.asar。')
  console.error('用法：node scripts/extract-theme.mjs --asar /path/to/app.asar')
  process.exit(1)
}

/** Minimal read-only asar reader (header is JSON at offset 16). */
function openAsar(file) {
  const buffer = readFileSync(file)
  const headerSize = buffer.readUInt32LE(12)
  const header = JSON.parse(buffer.slice(16, 16 + headerSize).toString('utf8'))
  const dataBase = 16 + headerSize
  return {
    header,
    read(entry) {
      return buffer.slice(
        dataBase + Number(entry.offset),
        dataBase + Number(entry.offset) + Number(entry.size)
      )
    },
    find(suffix) {
      let found = null
      const walk = (node, prefix) => {
        for (const [name, entry] of Object.entries(node.files ?? {})) {
          const path = prefix + '/' + name
          if (entry.files) walk(entry, path)
          else if (path.endsWith(suffix)) found = entry
        }
      }
      walk(header, '')
      return found
    }
  }
}

const asar = openAsar(asarPath)
const entry = asar.find('/dsh-client-ui-theme/lib/client.js')
if (!entry) {
  console.error('未在 asar 中找到 @deepseek-ai/dsh-client-ui-theme/lib/client.js。')
  process.exit(1)
}

const source = asar.read(entry).toString('utf8')
const cssChunks = []
for (const match of source.matchAll(/var ([a-zA-Z_0-9]+)_css_default = ("(?:\\.|[^"\\])*");/g)) {
  try {
    cssChunks.push(JSON.parse(match[2]))
  } catch {
    /* not a plain string literal; skip */
  }
}

// Keep only rules that declare CSS custom properties (token layer).
const tokenRules = []
for (const css of cssChunks) {
  for (const match of css.matchAll(/([^{}]+)\{([^{}]*--[^{}]*)\}/g)) {
    tokenRules.push(match[1].trim() + '{' + match[2].replace(/\s+/g, ' ').trim() + '}')
  }
}

const tokens = [
  ...new Set(tokenRules.join('\n').match(/--(?:dsw|dsh|ds)-[a-z0-9-]+/g) ?? [])
].sort()
const content = `/* Generated by scripts/extract-theme.mjs from the local host installation.
 * Product styling — do not redistribute. Git-ignored; used only for local
 * previews and the design gate. token count: ${tokens.length} */
${tokenRules.join('\n')}
`
writeFileSync(outPath, content)
console.log(`✅ ${outPath} (${tokenRules.length} rules, ${tokens.length} tokens)`)
console.log('   该文件已被 .gitignore 忽略，不要提交。')
